      dialog = 3,
      music = "48_Quiet_Daily",
      renwu = "npc",
      sentence = "假如说外向活泼的苹果箱是像小太阳一样耀眼的周棋洛，而Cello是那个慵懒又有趣的周棋洛……",
      next = {4}
