    },
    [6] = {
      beijing = 2523,
      dialog = 3,
      music = "48_Quiet_Daily",
      renwu = "npc",
      sentence = "在我们的“特殊关照”下，体型偏小的不亲人小猫一路成长，体重稳定飙升。",
